@OptIn(ExperimentalCoroutinesApi::class)
class InboxLinkClientTest {
    private fun fixture(n:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$n.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private fun source()=APIInboxLinkClientRepository(FixtureInboxLinkClientReadTransport.fromJSON(fixture("inbox-link-client")))
    private inner class Reads:InboxRepository,ClientSearchRepository {
        override suspend fun inbox(business:Int)=JsonContracts.inbox(fixture("inbox-$business"))
        override suspend fun thread(business:Int,id:Int)=JsonContracts.thread(fixture("inbox-$business-$id"))
        override suspend fun searchClients(business:Int,search:String)=JsonContracts.clients(FixtureClientSearch.list(fixture("client-search-catalogue-$business"),business,search).body)
        override suspend fun clientProfile(business:Int,id:Int)=JsonContracts.clientProfile(FixtureClientSearch.profile(fixture("client-search-catalogue-$business"),business,id).body)
    }
    private class Held(override val grants:List<SyntheticInboxLinkClientGrant>):SyntheticInboxLinkClientPort {val attempts=mutableListOf<InboxLinkClientAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxLinkClientOutcome>>();override suspend fun execute(a:InboxLinkClientAttempt):SyntheticInboxLinkClientOutcome {attempts+=a;return CompletableDeferred<SyntheticInboxLinkClientOutcome>().also {pending+=it}.await()}}
    private suspend fun candidate(x:JSONObject,s:InboxLinkClientSource):InboxLinkClientCandidate? {val profile=runCatching {Reads().clientProfile(x.getInt("profile_business"),x.getInt("profile_id"))}.getOrNull() ?: return null;return InboxLinkClientCandidate.make(s,ClientSearchProfileSelection(ClientSearchSelection(ClientSearchContext(x.getInt("search_business"),x.getInt("search_epoch")),x.getInt("selection_generation")),x.getInt("selected_id"),x.getInt("profile_generation")),ClientReadSelection(x.getInt("read_business"),x.getInt("read_id"),x.getInt("read_revision")),x.getString("raw_query"),profile)}
    @Test fun exactGenericSourceQualifiedReferenceTwoGrantsBodyPlain200AndUnknown()=runTest {
        val d=JSONObject(fixture("inbox-link-client"));val c=context(d.getJSONObject("context"));val rows=d.getJSONArray("source_cases");for(i in 0 until rows.length()){val x=rows.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkClientSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val s=InboxLinkClientSource.decode(d.getString("source_json"),c)!!;val candidates=d.getJSONArray("candidate_cases");for(i in 0 until candidates.length()){val x=candidates.getJSONObject(i);val choice=candidate(x,s);assertEquals(x.getString("name"),x.getBoolean("valid"),choice!=null);choice?.let {assertTrue(it.valid);assertEquals(x.getString("raw_query"),it.rawQuery)}}
        val f=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val auth=f.grants[0].authorization(c)!!;val choice=candidate(candidates.getJSONObject(0),s)!!;val r=InboxLinkClientReview(s,auth,choice,1);val l=InboxLinkClientLedger();val a=l.begin(r)!!;val body=JSONObject(a.preparedBody());assertEquals(setOf("client_id"),body.keys().asSequence().toSet());assertEquals(1701,body.getInt("client_id"));assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertEquals("/api/inbox/conversations/901/link-client/",a.path)
        val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkClientReceipt.decode(x.getString("response_json"),a)!=null)}
        assertNull(l.begin(r));assertFalse(l.acknowledge(auth,l.visible(auth)!!));l.complete(a,f.execute(a));val result=l.visible(auth)!!;assertEquals(InboxLinkClientPhase.RESPONSE,result.phase);assertEquals(1701,result.result!!.source.client);assertEquals(701,result.attempt.review.source.client);assertEquals(choice,result.attempt.review.candidate);l.complete(a,SyntheticInboxLinkClientOutcome.Unknown);assertEquals(result,l.visible(auth));assertTrue(l.acknowledge(auth,result));val second=l.begin(r)!!;l.complete(second,SyntheticInboxLinkClientOutcome.Unknown);val u=l.visible(auth)!!;assertFalse(l.acknowledge(auth,u));assertNull(l.begin(r));assertEquals(second,l.records[1].attempt)
        val next=c.copy(epoch=2,revision=2);val na=f.grants[0].authorization(next)!!;val matching=s.copy(context=next,client=1701);val row=JSONObject(candidates.getJSONObject(0).toString()).put("search_epoch",2).put("read_revision",2);val reread=candidate(row,matching)!!;assertEquals(u,l.visible(na));assertNull(l.begin(InboxLinkClientReview(matching,na,reread,2)));val other=SyntheticInboxLinkClientGrant(101,901,6002,true,true).authorization(next)!!;assertNull(l.visible(other));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
        for(g in listOf(SyntheticInboxLinkClientGrant(101,901,5001,false,true),SyntheticInboxLinkClientGrant(101,901,5001,true,false),SyntheticInboxLinkClientGrant(202,901,5001,true,true),SyntheticInboxLinkClientGrant(101,951,5001,true,true),SyntheticInboxLinkClientGrant(101,901,0,true,true)))assertNull(g.authorization(c))
        for(status in listOf(201,400,403,409,500)){val x=InboxLinkClientLedger();val a=x.begin(r)!!;x.complete(a,SyntheticInboxLinkClientOutcome.Response(status,"{}"));assertEquals(InboxLinkClientPhase.UNKNOWN,x.visible(auth)!!.phase);assertFalse(x.acknowledge(auth,x.visible(auth)!!))}
    }
    @Test fun actualParentManualQueryProfileChoicePendingKnownUnknownAndABA()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val reads=Reads();val f=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val held=Held(f.grants);val m=InboxViewModel(reads,files=files(),linkRead=source(),linkClients=reads,linkSubmission=held)
        try {m.load(101,541);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val container=m.fileMetadata!!;val link=container.linkClient!!;val p=link.picker!!;m.openFiles(m.filesEntryControl);assertNull(link.source);assertNull(p.state.selection);assertFalse(link.canOpen);link.load(link.control);assertEquals(701,link.source!!.client);link.open(link.control);val input=link.input!!;link.update(" synthetic é ",input);link.update("",input);assertTrue(p.state.query.isEmpty());val old=link.control;val oldWindow=p.control;link.search(link.control,p.control);runCurrent();assertEquals(50,p.state.items.size);assertEquals(54,p.state.total);assertTrue(p.state.partial);assertNull(link.candidate);link.openClient(1701,old,oldWindow);runCurrent();assertNull(p.state.profileSelection);link.openClient(1701,link.control,p.control);runCurrent();assertEquals(1701,p.profile.readSelection!!.id);assertNull(link.candidate);val use=link.control;link.useClient(use,p.control);val choice=link.candidate!!;assertEquals(1701,choice.choice.id);assertTrue(link.canPrepare);link.clearChoice(use);assertEquals(choice,link.candidate);link.clearChoice(link.control);assertNull(link.candidate);link.useClient(link.control,p.control);link.prepare(link.control);val r=link.review;link.clearChoice(link.control);assertEquals(r,link.review);assertTrue(link.canSubmit);link.back(link.control);assertTrue(link.canPrepare);link.prepare(link.control);val submit=link.control;val job=launch {link.submit(submit)};runCurrent();val pending=link.record!!;link.submit(link.control);link.acknowledge(pending,link.control);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);m.closeFiles(m.filesPresentationControl);m.openReply(m.reply.state.context!!,m.control);m.openHandoff(m.handoff.entryControl,m.control);assertNull(m.reply.control);assertNull(m.handoff.control);m.openFiles(m.filesEntryControl);link.load(link.control);assertEquals(pending,link.record);assertNull(link.source);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val response=link.record!!;assertEquals(InboxLinkClientPhase.RESPONSE,response.phase);assertEquals(1701,response.result!!.source.client);assertEquals(701,response.attempt.review.source.client);assertEquals(original,m.state.thread);link.acknowledge(response,submit);assertEquals(response,link.record);link.acknowledge(response,link.control);assertNull(link.source);assertFalse(link.canOpen);assertEquals(1,link.retainedAttemptCount)
            link.load(link.control);link.open(link.control);link.update("",link.input);link.search(link.control,p.control);runCurrent();link.openClient(1702,link.control,p.control);runCurrent();link.useClient(link.control,p.control);link.prepare(link.control);val uc=link.control;val uj=launch {link.submit(uc)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic failure"));uj.join();val unknown=link.record!!;link.load(link.control);link.acknowledge(unknown,link.control);link.open(link.control);assertEquals(InboxLinkClientPhase.UNKNOWN,unknown.phase);assertEquals(1702,unknown.attempt.review.candidate.choice.id);assertEquals(unknown,link.record);assertFalse(link.canOpen);m.closeFiles(m.filesPresentationControl);m.load(202,542);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);link.load(link.control);assertNull(link.record);assertTrue(link.canOpen);assertNull(link.candidate);m.closeFiles(m.filesPresentationControl);m.load(101,543);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);link.load(link.control);assertEquals(unknown,link.record);assertFalse(link.canOpen)
        } finally {m.viewModelScope.cancel();Dispatchers.resetMain()}
    }
    @Test fun absentOrMissingOneGrantCannotOpenPickerAndCancelledAttemptKeepsCandidate()=runTest {
        val f=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val reads=Reads();val c=InboxConversationFilesContext(101,901,544,1)
        for(grants in listOf(emptyList(),listOf(SyntheticInboxLinkClientGrant(101,901,5001,false,true)),listOf(SyntheticInboxLinkClientGrant(101,901,5001,true,false)))){val m=InboxLinkClientModel(source(),reads,Held(grants),this);m.commandsBlocked={false};m.bind(c);m.show();m.load(m.control);m.open(m.control);assertNotNull(m.source);assertFalse(m.canOpen);assertNull(m.picker!!.state.selection)}
        val held=Held(f.grants);val m=InboxLinkClientModel(source(),reads,held,this);m.commandsBlocked={false};m.bind(c);m.show();m.load(m.control);m.open(m.control);val p=m.picker!!;m.search(m.control,p.control);runCurrent();m.openClient(1701,m.control,p.control);runCurrent();m.useClient(m.control,p.control);m.prepare(m.control);val review=m.review!!;val before=m.control;val job=launch {m.submit(before)};runCurrent();job.cancelAndJoin();assertEquals(InboxLinkClientPhase.UNKNOWN,m.record!!.phase);assertEquals(review,m.record!!.attempt.review);assertFalse(m.canOpen)
    }
    @Test fun lateCommandGenericReadAndProfileCannotDisplaceNewBusinessQuery()=runTest {
        val reads=Reads();val f=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val held=Held(f.grants);val ac=InboxConversationFilesContext(101,901,546,1);val bc=InboxConversationFilesContext(202,951,547,1);val m=InboxLinkClientModel(source(),reads,held,this);m.commandsBlocked={false};m.bind(ac);m.show();m.load(m.control);m.open(m.control);val p=m.picker!!;m.search(m.control,p.control);runCurrent();m.openClient(1701,m.control,p.control);runCurrent();m.useClient(m.control,p.control);m.prepare(m.control);val ctrl=m.control;val job=launch {m.submit(ctrl)};runCurrent();val a=held.attempts[0];m.hide();m.bind(bc);m.show();m.load(m.control);m.open(m.control);m.update(" B raw query é ",m.input);val before=m.control;held.pending[0].complete(f.execute(a));job.join();assertEquals(before,m.control);assertEquals(" B raw query é ",p.state.query);assertNull(m.record);assertNull(m.candidate);assertEquals(1,m.retainedAttemptCount)
        val deferred=CompletableDeferred<InboxLinkClientSource>();val repo=object:InboxLinkClientRepository {override suspend fun source(c:InboxConversationFilesContext)=deferred.await()};val late=InboxLinkClientModel(repo,reads,f,this);late.commandsBlocked={false};late.bind(ac);late.show();val old=late.control;val get=launch {late.load(old)};runCurrent();late.hide();late.bind(bc);late.show();val next=late.control;deferred.complete(source().source(ac));get.join();assertEquals(next,late.control);assertNull(late.source);assertFalse(late.loading)
        val profileDeferred=CompletableDeferred<ClientProfile>();val profiles=object:ClientSearchRepository {override suspend fun searchClients(business:Int,search:String)=reads.searchClients(business,search);override suspend fun clientProfile(business:Int,id:Int)=profileDeferred.await()};val lm=InboxLinkClientModel(source(),profiles,f,this);lm.commandsBlocked={false};lm.bind(ac);lm.show();lm.load(lm.control);lm.open(lm.control);val pp=lm.picker!!;lm.search(lm.control,pp.control);runCurrent();val oldControl=lm.control;val oldChild=pp.control;lm.openClient(1701,lm.control,pp.control);runCurrent();lm.hide();lm.bind(bc);lm.show();lm.load(lm.control);lm.open(lm.control);lm.update(" Current B profile query ",lm.input);val current=lm.control;profileDeferred.complete(reads.clientProfile(101,1701));runCurrent();lm.useClient(oldControl,oldChild);assertEquals(current,lm.control);assertEquals(" Current B profile query ",pp.state.query);assertNull(pp.profile.state.detail);assertNull(lm.candidate)
    }

}
